import { readdirSync, statSync, writeFileSync } from 'node:fs'
import { join, relative, resolve } from 'node:path'
import type { Plugin } from 'vite'

type Options = {
  pagesDir?: string
  outFile?: string
  exclude?: (name: string) => boolean
}

const isLayoutOrResolver = (name: string) =>
  name === 'Layout' || name === 'resolvePage' || name.endsWith('/Layout')

/**
 * Scans `app/pages/**\/*.tsx` and writes a `PageName` string-union type to
 * `app/pages.gen.ts`, so `c.render(name, props)` on the server is checked
 * against the pages that actually exist. Regenerated on build start and on
 * page add/remove during dev.
 */
export const inertiaPages = (options: Options = {}): Plugin => {
  const cwd = process.cwd()
  const pagesDir = resolve(cwd, options.pagesDir ?? 'app/pages')
  const outFile = resolve(cwd, options.outFile ?? 'app/pages.gen.ts')
  const exclude = options.exclude ?? isLayoutOrResolver

  const collect = (): string[] => {
    const pages: string[] = []
    const walk = (dir: string) => {
      for (const entry of readdirSync(dir)) {
        const full = join(dir, entry)
        if (statSync(full).isDirectory()) {
          walk(full)
          continue
        }
        if (!entry.endsWith('.tsx')) continue
        const name = relative(pagesDir, full).replace(/\.tsx$/, '').replaceAll('\\', '/')
        if (!exclude(name)) pages.push(name)
      }
    }
    walk(pagesDir)
    return pages.sort()
  }

  const generate = () => {
    const pages = collect()
    const union = pages.length ? pages.map((p) => `'${p}'`).join(' | ') : 'never'
    writeFileSync(
      outFile,
      `// AUTO-GENERATED by vite-plugins/inertia-pages.ts. Do not edit.\nexport type PageName = ${union}\n`
    )
  }

  return {
    name: 'inertia-pages',
    buildStart() {
      generate()
    },
    configureServer(server) {
      generate()
      const onChange = (file: string) => {
        if (file.startsWith(pagesDir) && file.endsWith('.tsx')) generate()
      }
      server.watcher.on('add', onChange)
      server.watcher.on('unlink', onChange)
    }
  }
}
